import { getCustomer } from './customers.js';
import { ok, fail } from './result.js';
import { balanceDue, invoiceTotals } from './invoices.js';

/**
 * Generate a customer statement for invoices issued by a certain date.
 * @param {string} customerId
 * @param {Array<object>} invoices - Array of invoice objects
 * @param {string} asOf - Date in YYYY-MM-DD format
 * @returns {{ ok: true, value: { customerId: string, invoices: Array<{ number: string, issueDate: string, dueDate: string, total: number, due: number }>, totalDue: number } } | { ok: false, error: string }}
 */
export function statement(customerId, invoices, asOf) {
  // Validate customer exists
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) return fail('CUSTOMER_NOT_FOUND');

  // Filter invoices: matching customer, issued or partially paid, issued on or before asOf
  const relevantInvoices = invoices
    .filter(inv => inv.customerId === customerId)
    .filter(inv => ['issued', 'partially_paid'].includes(inv.status))
    .filter(inv => inv.issueDate <= asOf)
    .sort((a, b) => a.issueDate.localeCompare(b.issueDate));

  // Build statement items
  const statementInvoices = relevantInvoices.map(inv => {
    const totals = invoiceTotals(inv);
    const due = balanceDue(inv);
    return {
      number: inv.number,
      issueDate: inv.issueDate,
      dueDate: inv.dueDate,
      total: totals.total,
      due,
    };
  });

  // Calculate total due
  const totalDue = statementInvoices.reduce((sum, inv) => sum + inv.due, 0);

  return ok({
    customerId,
    invoices: statementInvoices,
    totalDue,
  });
}

