test('statement sorts invoices by issueDate', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const inv2Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const inv3Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const inv1 = issueInvoice(inv1Result.value, ['INV-2026-0003']).value;
  const inv2 = issueInvoice(inv2Result.value, ['INV-2026-0003', 'INV-2026-0001']).value;
  const inv3 = issueInvoice(inv3Result.value, ['INV-2026-0003', 'INV-2026-0001', 'INV-2026-0002']).value;

  const result = statement('C-001', [inv1, inv2, inv3], '2026-10-31');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 3);
  assert.equal(result.value.invoices[0].issueDate, '2026-10-05');
  assert.equal(result.value.invoices[1].issueDate, '2026-10-10');
  assert.equal(result.value.invoices[2].issueDate, '2026-10-15');
});

test('statement includes all invoice fields', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });

  const inv = issueInvoice(invResult.value, []).value;

  const result = statement('C-001', [inv], '2026-10-31');

  assert.equal(result.ok, true);
  const invoiceItem = result.value.invoices[0];
  assert.ok(invoiceItem.number);
  assert.ok(invoiceItem.issueDate);
  assert.ok(invoiceItem.dueDate);
  assert.equal(invoiceItem.dueDate, '2026-10-15');
  assert.equal(typeof invoiceItem.total, 'number');
  assert.equal(typeof invoiceItem.due, 'number');
});

test('statement calculates totalDue as sum of individual dues', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const inv2Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-02',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  const inv1 = issueInvoice(inv1Result.value, []).value;
  const inv2 = issueInvoice(inv2Result.value, ['INV-2026-0001']).value;

  const result = statement('C-001', [inv1, inv2], '2026-10-31');

  assert.equal(result.ok, true);
  const totalDue = result.value.invoices.reduce((sum, inv) => sum + inv.due, 0);
  assert.equal(result.value.totalDue, totalDue);
});

test('statement handles partial payments in totalDue', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const invIssued = issueInvoice(invResult.value, []).value;
  const invPartial = recordPayment(invIssued, { amount: 10000, date: '2026-10-10' }).value;

  const result = statement('C-001', [invPartial], '2026-10-31');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices[0].due, result.value.totalDue);
});

test('statement returns empty invoices array when no invoices match', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const inv = issueInvoice(invResult.value, []).value;

  const result = statement('C-001', [inv], '2026-09-30');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
  assert.equal(result.value.totalDue, 0);
});

test('statement reports unknown customer', () => {
  assert.deepEqual(
