  assert.equal(result.ok, true);
  assert.equal(result.value.invoices[0].due, 0);
  assert.equal(result.value.totalDue, 0);
});

test('statement with multiple invoices and mixed payment status', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const inv2Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const inv3Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const inv1Issued = issueInvoice(inv1Result.value, []).value;
  const inv1Paid = recordPayment(inv1Issued, { amount: 51425, date: '2026-10-02' }).value;

  const inv2Issued = issueInvoice(inv2Result.value, ['INV-2026-0001']).value;
  const inv2Partial = recordPayment(inv2Issued, { amount: 20000, date: '2026-10-06' }).value;

  const inv3 = issueInvoice(inv3Result.value, ['INV-2026-0001', 'INV-2026-0002']).value;

  const result = statement('C-001', [inv1Paid, inv2Partial, inv3], '2026-10-31');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 3);
  assert.equal(result.value.invoices[0].due, 0); // Paid
  assert.ok(result.value.invoices[1].due > 0); // Partially paid
  assert.ok(result.value.invoices[2].due > 0); // Unpaid
  assert.equal(result.value.totalDue, result.value.invoices[1].due + result.value.invoices[2].due);
});

