import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';
import { statement } from '../src/statements.js';

test('statement returns invoices for a customer', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const inv1 = issueInvoice(inv1Result.value, []).value;

  const result = statement('C-001', [inv1], '2026-10-31');

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].number, 'INV-2026-0001');
  assert.equal(result.value.invoices[0].issueDate, '2026-10-01');
});

test('statement filters invoices by customer', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const inv2Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-02',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const inv1 = issueInvoice(inv1Result.value, []).value;
  const inv2 = issueInvoice(inv2Result.value, []).value;

  const result = statement('C-001', [inv1, inv2], '2026-10-31');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].number, 'INV-2026-0001');
});

test('statement filters by status (issued only)', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const inv2 = inv1Result.value; // Still draft

  const inv3Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-02',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const inv3 = issueInvoice(inv3Result.value, []).value; // Issued

  const result = statement('C-001', [inv2, inv3], '2026-10-31');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].number, 'INV-2026-0001');
});

test('statement filters by status (partially_paid included)', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const inv1Issued = issueInvoice(inv1Result.value, []).value;
  const inv1Partial = recordPayment(inv1Issued, { amount: 10000, date: '2026-10-10' }).value;

  const result = statement('C-001', [inv1Partial], '2026-10-31');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].number, 'INV-2026-0001');
  // C-001 is gold tier (5% discount): 42500 - 2125 + 8479 = 48854; 48854 - 10000 = 38854
  assert.equal(result.value.invoices[0].due, 38854);
});

test('statement filters by asOf date', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const inv2Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const inv1 = issueInvoice(inv1Result.value, []).value;
  const inv2 = issueInvoice(inv2Result.value, []).value;

  const result = statement('C-001', [inv1, inv2], '2026-10-10');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].issueDate, '2026-10-01');
});

test('statement includes invoices with issueDate equal to asOf', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const inv = issueInvoice(invResult.value, []).value;

  const result = statement('C-001', [inv], '2026-10-01');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
});

test('statement sorts invoices by issueDate', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const inv2Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const inv3Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const inv1 = issueInvoice(inv1Result.value, ['INV-2026-0003']).value;
  const inv2 = issueInvoice(inv2Result.value, ['INV-2026-0003', 'INV-2026-0001']).value;
  const inv3 = issueInvoice(inv3Result.value, ['INV-2026-0003', 'INV-2026-0001', 'INV-2026-0002']).value;

  const result = statement('C-001', [inv1, inv2, inv3], '2026-10-31');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 3);
  assert.equal(result.value.invoices[0].issueDate, '2026-10-05');
  assert.equal(result.value.invoices[1].issueDate, '2026-10-10');
  assert.equal(result.value.invoices[2].issueDate, '2026-10-15');
});

test('statement includes all invoice fields', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });

  const inv = issueInvoice(invResult.value, []).value;

  const result = statement('C-001', [inv], '2026-10-31');

  assert.equal(result.ok, true);
  const invoiceItem = result.value.invoices[0];
  assert.ok(invoiceItem.number);
  assert.ok(invoiceItem.issueDate);
  assert.ok(invoiceItem.dueDate);
  assert.equal(invoiceItem.dueDate, '2026-10-15');
  assert.equal(typeof invoiceItem.total, 'number');
  assert.equal(typeof invoiceItem.due, 'number');
});

test('statement calculates totalDue as sum of individual dues', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const inv2Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-02',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  const inv1 = issueInvoice(inv1Result.value, []).value;
  const inv2 = issueInvoice(inv2Result.value, ['INV-2026-0001']).value;

  const result = statement('C-001', [inv1, inv2], '2026-10-31');

  assert.equal(result.ok, true);
  const totalDue = result.value.invoices.reduce((sum, inv) => sum + inv.due, 0);
  assert.equal(result.value.totalDue, totalDue);
});

test('statement handles partial payments in totalDue', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const invIssued = issueInvoice(invResult.value, []).value;
  const invPartial = recordPayment(invIssued, { amount: 10000, date: '2026-10-10' }).value;

  const result = statement('C-001', [invPartial], '2026-10-31');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices[0].due, result.value.totalDue);
});

test('statement returns empty invoices array when no invoices match', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const inv = issueInvoice(invResult.value, []).value;

  const result = statement('C-001', [inv], '2026-09-30');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
  assert.equal(result.value.totalDue, 0);
});

test('statement reports unknown customer', () => {
  assert.deepEqual(
    statement('C-999', [], '2026-10-31'),
    { ok: false, error: 'CUSTOMER_NOT_FOUND' }
  );
});

test('statement excludes paid invoices from statement', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const inv1Issued = issueInvoice(invResult.value, []);
  assert.equal(inv1Issued.ok, true);

  const invPaid = recordPayment(inv1Issued.value, { amount: 48854, date: '2026-10-10' });
  assert.equal(invPaid.ok, true);

  const result = statement('C-001', [invPaid.value], '2026-10-31');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
  assert.equal(result.value.totalDue, 0);
});

